import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';

// The checked-in ERD is a review artifact, never regenerated by the tests themselves.
export function parseSchema(source) {
  const blocks = [...source.matchAll(/^model\s+(\w+)\s*\{([\s\S]*?)^\}/gm)];
  const names = new Set(blocks.map((m) => m[1]));
  assert.ok(names.size > 30, 'Complete foundation Prisma schema required');
  return blocks
    .map(([, name, body]) => {
      const table = body.match(/@@map\("([^"]+)"\)/)?.[1] ?? name;
      const fields = [],
        relations = [];
      const uniqueSets = [...body.matchAll(/@@(?:unique|id)\(\[([^\]]+)\]([^\n]*)/g)]
        .filter((m) => !m[2].includes('where:'))
        .map((m) => m[1].split(',').map((x) => x.trim()));
      for (const line of body.split('\n')) {
        const m = line.match(/^\s+(\w+)\s+(\w+)(\[\]|\?)?\s*(.*)$/);
        if (!m) continue;
        const [, field, type, suffix, attributes] = m;
        if (names.has(type)) {
          const from = attributes.match(/fields:\s*\[([^\]]+)\]/)?.[1];
          const to = attributes.match(/references:\s*\[([^\]]+)\]/)?.[1];
          if (from && to)
            relations.push({
              field,
              type,
              from: from.split(',').map((x) => x.trim()),
              to: to.split(',').map((x) => x.trim()),
              constraint: attributes.match(/map:\s*"([^"]+)"/)?.[1] ?? null,
            });
        } else {
          fields.push({
            name: field,
            column: attributes.match(/@map\("([^"]+)"\)/)?.[1] ?? field,
            type,
            list: suffix === '[]',
            nullable: suffix === '?',
            primary: /@id\b/.test(attributes),
            native:
              attributes
                .match(/@db\.(\w+)(?:\(([^)]+)\))?/)
                ?.slice(1)
                .filter((x) => x !== undefined) ?? null,
          });
          if (/@(?:id|unique)\b/.test(attributes)) uniqueSets.push([field]);
        }
      }
      assert.ok(fields.length, `No columns parsed for ${name}`);
      return { name, table, fields, relations, uniqueSets };
    })
    .sort((a, b) => a.table.localeCompare(b.table));
}
export function renderErd(models) {
  const byName = new Map(models.map((m) => [m.name, m]));
  const lines = [
    '# Foundation ERD',
    '',
    'Generated from the reviewed Prisma schema. SQL-only guards are verified separately against PostgreSQL catalog metadata.',
    '',
    '```mermaid',
    'erDiagram',
  ];
  for (const model of models) {
    lines.push(`  ${model.table} {`);
    for (const field of model.fields)
      lines.push(
        `    ${field.type}${field.list ? '_array' : ''} ${field.column}${field.primary ? ' PK' : ''}`,
      );
    lines.push('  }');
    for (const relation of model.relations) {
      const optional = relation.from.some(
        (name) => model.fields.find((f) => f.name === name)?.nullable,
      );
      const unique = model.uniqueSets.some((set) =>
        set.every((name) => relation.from.includes(name)),
      );
      lines.push(
        `  ${byName.get(relation.type).table} ${optional ? 'o|' : '||'}--${unique ? 'o|' : 'o{'} ${model.table} : "${relation.constraint ?? relation.field}"`,
      );
    }
  }
  lines.push(
    '```',
    '',
    'Cardinality marks show the referenced-to-dependent direction. Nullable columns and compound FK columns are specified in `schema.contract.json`.',
    'Financial immutability, exclusion constraints, partial unique indexes, RLS and runtime grants are additional SQL invariants, not ORM-only guarantees.',
    '',
  );
  return lines.join('\n');
}
if (process.argv.includes('--write')) {
  const models = parseSchema(
    await readFile(new URL('../../packages/db/prisma/schema.prisma', import.meta.url), 'utf8'),
  );
  await writeFile(
    new URL('../../packages/db/schema.contract.json', import.meta.url),
    JSON.stringify(models, null, 2) + '\n',
  );
  await writeFile(new URL('../../packages/db/ERD.md', import.meta.url), renderErd(models));
  console.log(
    `ERD recorded: ${models.length} models, ${models.reduce((n, m) => n + m.relations.length, 0)} foreign keys`,
  );
}
